<?php
declare(strict_types=1);

function isAreaLeader(PDO $pdo, int $userId): bool
{
    $statement=$pdo->prepare("SELECT 1 FROM user_roles ur INNER JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=:user AND ur.is_active=1 AND r.is_active=1 AND r.code IN ('AREA_ADMIN','AREA_MANAGER') LIMIT 1");
    $statement->execute(['user'=>$userId]);
    return (bool)$statement->fetchColumn();
}

function userHasPermission(PDO $pdo, int $userId, string $moduleCode, string $actionCode): bool
{
    if(isSuperAdmin($pdo,$userId)) return true;
    $deny=$pdo->prepare("SELECT 1 FROM user_permission_overrides o INNER JOIN permissions p ON p.id=o.permission_id INNER JOIN app_modules m ON m.id=p.module_id WHERE o.user_id=:user AND o.decision='DENY' AND m.code=:module AND p.action_code=:action LIMIT 1");
    $deny->execute(['user'=>$userId,'module'=>$moduleCode,'action'=>$actionCode]);
    if($deny->fetchColumn()) return false;
    $allow=$pdo->prepare("SELECT 1 FROM permissions p INNER JOIN app_modules m ON m.id=p.module_id WHERE m.code=:module AND p.action_code=:action AND (EXISTS(SELECT 1 FROM user_roles ur INNER JOIN role_permissions rp ON rp.role_id=ur.role_id WHERE ur.user_id=:role_user AND ur.is_active=1 AND rp.permission_id=p.id) OR EXISTS(SELECT 1 FROM user_permission_overrides o WHERE o.user_id=:override_user AND o.permission_id=p.id AND o.decision='ALLOW')) LIMIT 1");
    $allow->execute(['module'=>$moduleCode,'action'=>$actionCode,'role_user'=>$userId,'override_user'=>$userId]);
    return (bool)$allow->fetchColumn();
}

function requireArea(PDO $pdo, array $user, array $areaCodes): void
{
    if(isSuperAdmin($pdo,(int)$user['id']))return;
    $marks=implode(',',array_fill(0,count($areaCodes),'?'));$statement=$pdo->prepare("SELECT 1 FROM areas WHERE id=? AND code IN ({$marks}) AND is_active=1");$statement->execute(array_merge([(int)$user['primary_area_id']],$areaCodes));if(!$statement->fetchColumn())failRequest('Esta captura corresponde a otra área.',403);
}

function buildLookups(PDO $pdo, array $user, bool $isAdmin): array
{
    $areas=$isAdmin?safeRows($pdo,"SELECT id,code,name FROM areas WHERE is_active=1 ORDER BY name"):safeRows($pdo,"SELECT id,code,name FROM areas WHERE id=:id AND is_active=1",['id'=>$user['primary_area_id']]);
    $roles=$isAdmin?safeRows($pdo,"SELECT id,code,name FROM roles WHERE is_active=1 AND code<>'SUPER_ADMIN' ORDER BY is_system DESC,name"):safeRows($pdo,"SELECT id,code,name FROM roles WHERE is_active=1 AND code IN ('OPERATOR','APPROVER','VIEWER','TECHNICIAN') ORDER BY id");
    $moduleSql="SELECT DISTINCT m.id,m.code,m.name,m.sort_order FROM app_modules m WHERE m.is_active=1 AND m.code IN ('DASHBOARD','WAREHOUSE_RAW','WAREHOUSE_PACKAGING','WAREHOUSE_SPARES','WAREHOUSE_FINISHED','INVENTORY','COUNTS','PURCHASING','QUALITY','QUALITY_ANALYTICS','FILLING','EXTRACTION','MAINTENANCE','FORECAST','MRP','SHIPPING','RETURNS')";
    $modules=$isAdmin?safeRows($pdo,$moduleSql." ORDER BY m.sort_order"):safeRows($pdo,$moduleSql." AND EXISTS(SELECT 1 FROM permissions p WHERE p.module_id=m.id AND p.action_code='VIEW' AND (EXISTS(SELECT 1 FROM user_roles ur INNER JOIN role_permissions rp ON rp.role_id=ur.role_id WHERE ur.user_id=:user1 AND ur.is_active=1 AND rp.permission_id=p.id) OR EXISTS(SELECT 1 FROM user_permission_overrides o WHERE o.user_id=:user2 AND o.permission_id=p.id AND o.decision='ALLOW'))) ORDER BY m.sort_order",['user1'=>$user['id'],'user2'=>$user['id']]);
    $canInventory=$isAdmin||userHasPermission($pdo,(int)$user['id'],'INVENTORY','VIEW')||userHasPermission($pdo,(int)$user['id'],'INITIAL_INVENTORY','VIEW')||userHasPermission($pdo,(int)$user['id'],'COUNTS','VIEW')||userHasPermission($pdo,(int)$user['id'],'RECEIVING','VIEW')||hasAnyPermissionV14($pdo,(int)$user['id'],['WAREHOUSE_RAW','WAREHOUSE_PACKAGING','WAREHOUSE_SPARES','WAREHOUSE_FINISHED'],'VIEW');
    $canCatalogs=$isAdmin||userHasPermission($pdo,(int)$user['id'],'CATALOGS','VIEW')||hasAnyPermissionV14($pdo,(int)$user['id'],['WAREHOUSE_RAW','WAREHOUSE_PACKAGING','WAREHOUSE_SPARES','WAREHOUSE_FINISHED','FILLING'],'VIEW');
    $canForecast=$isAdmin||userHasPermission($pdo,(int)$user['id'],'FORECAST','VIEW')||userHasPermission($pdo,(int)$user['id'],'MRP','VIEW')||userHasPermission($pdo,(int)$user['id'],'FILLING','VIEW');
    $canSuppliers=$isAdmin||userHasPermission($pdo,(int)$user['id'],'PURCHASING','VIEW')||userHasPermission($pdo,(int)$user['id'],'APPOINTMENTS','VIEW')||userHasPermission($pdo,(int)$user['id'],'RECEIVING','VIEW');
    $canCustomers=$isAdmin||$canForecast||userHasPermission($pdo,(int)$user['id'],'SHIPPING','VIEW')||userHasPermission($pdo,(int)$user['id'],'RETURNS','VIEW')||userHasPermission($pdo,(int)$user['id'],'PRODUCTION','VIEW');
    $canMaintenance=$isAdmin||userHasPermission($pdo,(int)$user['id'],'MAINTENANCE','VIEW');
    $userAreaCode=(string)($areas[0]['code']??'');
    [$maintenanceFilter,$maintenanceParams]=maintenanceVisibility($pdo,$user,'r');
    return [
        'areas'=>$areas,'roles'=>$roles,'modules'=>$modules,
        'warehouses'=>$canInventory||$canCatalogs?safeRows($pdo,"SELECT id,code,name,warehouse_type FROM warehouses WHERE is_active=1 AND code NOT LIKE 'EJ-%' ORDER BY name"):[],
        'locations'=>$canInventory||$canCatalogs?safeRows($pdo,"SELECT l.id,l.warehouse_id,l.code,l.name,l.location_type,l.is_blocked,w.name AS warehouse_name,w.warehouse_type FROM warehouse_locations l INNER JOIN warehouses w ON w.id=l.warehouse_id WHERE l.is_active=1 AND w.is_active=1 AND w.code NOT LIKE 'EJ-%' ORDER BY w.name,l.name"):[],
        'items'=>$canInventory||$canCatalogs?safeRows($pdo,"SELECT i.id,i.sku,i.name,i.item_type,i.lot_controlled,i.quality_required,i.base_uom_id,u.code AS uom_code,u.name AS uom_name FROM items i INNER JOIN units_of_measure u ON u.id=i.base_uom_id WHERE i.is_active=1 AND i.sku NOT LIKE 'EJ-%' ORDER BY i.name"):[],
        'categories'=>$canCatalogs?safeRows($pdo,"SELECT code,name FROM item_categories WHERE is_active=1 ORDER BY name"):[],
        'units'=>$canCatalogs?safeRows($pdo,"SELECT code,name FROM units_of_measure ORDER BY name"):[],
        'finishedGoods'=>$canForecast||$canCatalogs?safeRows($pdo,"SELECT id,sku,name FROM items WHERE is_active=1 AND item_type='FINISHED_GOOD' AND sku NOT LIKE 'EJ-%' ORDER BY name"):[],
        'suppliers'=>$canSuppliers||($canCatalogs&&($isAdmin||$userAreaCode==='COMPRAS'))?safeRows($pdo,"SELECT id,supplier_code,COALESCE(trade_name,legal_name) AS name FROM suppliers WHERE is_active=1 AND supplier_code NOT LIKE 'EJ-%' ORDER BY name"):[],
        'customers'=>$canCustomers||($canCatalogs&&($isAdmin||$userAreaCode==='VENTAS'))?safeRows($pdo,"SELECT id,customer_code,COALESCE(trade_name,legal_name) AS name FROM customers WHERE is_active=1 AND customer_code NOT LIKE 'EJ-%' ORDER BY name"):[],
        'assets'=>$canMaintenance?safeRows($pdo,"SELECT id,asset_code,asset_name FROM maintenance_assets WHERE is_active=1 AND asset_code NOT LIKE 'EJ-%' ORDER BY asset_name"):[],
        'technicians'=>$canMaintenance&&isMaintenanceLeader($pdo,$user)?safeRows($pdo,"SELECT u.id,u.display_name AS name,u.email,t.specialties,t.phone FROM maintenance_technicians t INNER JOIN app_users u ON u.id=t.user_id WHERE t.is_active=1 AND u.status='ACTIVE' ORDER BY u.display_name"):[],
        'maintenanceRequests'=>$canMaintenance?safeRows($pdo,"SELECT r.id,r.request_number,r.title,r.status FROM maintenance_work_requests r {$maintenanceFilter} AND r.status NOT IN ('VERIFIED','CANCELLED') ORDER BY r.created_at DESC",$maintenanceParams):[],
    ];
}

function maintenanceVisibility(PDO $pdo, array $user, string $alias='r'): array
{
    if(isSuperAdmin($pdo,(int)$user['id'])||isMaintenanceLeader($pdo,$user))return ['WHERE 1=1',[]];
    if(isAreaLeader($pdo,(int)$user['id']))return ["WHERE ({$alias}.requesting_area_id=:visible_area OR {$alias}.requested_by=:visible_requester OR EXISTS(SELECT 1 FROM maintenance_work_assignments visible_assignment WHERE visible_assignment.work_request_id={$alias}.id AND visible_assignment.technician_user_id=:visible_technician AND visible_assignment.assignment_status<>'CANCELLED'))",['visible_area'=>$user['primary_area_id'],'visible_requester'=>$user['id'],'visible_technician'=>$user['id']]];
    return ["WHERE ({$alias}.requested_by=:visible_requester OR EXISTS(SELECT 1 FROM maintenance_work_assignments visible_assignment WHERE visible_assignment.work_request_id={$alias}.id AND visible_assignment.technician_user_id=:visible_technician AND visible_assignment.assignment_status<>'CANCELLED'))",['visible_requester'=>$user['id'],'visible_technician'=>$user['id']]];
}

function buildUserList(PDO $pdo, array $user, bool $isAdmin): array
{
    $where=$isAdmin?'':'WHERE u.primary_area_id=:area';
    $params=$isAdmin?[]:['area'=>$user['primary_area_id']];
    return safeRows($pdo,"SELECT
        u.id,u.display_name AS name,u.email,u.phone_number AS phone,u.primary_area_id AS primaryAreaId,
        COALESCE(a.name,'Sin área') AS area,
        COALESCE((SELECT r.name FROM user_roles ur INNER JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=u.id AND ur.is_active=1 ORDER BY r.id LIMIT 1),'Sin rol') AS role,
        COALESCE((SELECT r.code FROM user_roles ur INNER JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=u.id AND ur.is_active=1 ORDER BY r.id LIMIT 1),'') AS roleCode,
        COALESCE((SELECT GROUP_CONCAT(DISTINCT m.name ORDER BY m.sort_order SEPARATOR ', ')
          FROM app_modules m INNER JOIN permissions p ON p.module_id=m.id AND p.action_code='VIEW'
          WHERE m.is_active=1
            AND (EXISTS(SELECT 1 FROM user_roles ur INNER JOIN role_permissions rp ON rp.role_id=ur.role_id WHERE ur.user_id=u.id AND ur.is_active=1 AND rp.permission_id=p.id)
              OR EXISTS(SELECT 1 FROM user_permission_overrides allow_override WHERE allow_override.user_id=u.id AND allow_override.permission_id=p.id AND allow_override.decision='ALLOW'))
            AND NOT EXISTS(SELECT 1 FROM user_permission_overrides deny_override WHERE deny_override.user_id=u.id AND deny_override.permission_id=p.id AND deny_override.decision='DENY')),'Acceso total') AS modules,
        COALESCE((SELECT GROUP_CONCAT(DISTINCT m.code ORDER BY m.sort_order SEPARATOR ',')
          FROM app_modules m INNER JOIN permissions p ON p.module_id=m.id AND p.action_code='VIEW'
          WHERE m.is_active=1
            AND (EXISTS(SELECT 1 FROM user_roles ur INNER JOIN role_permissions rp ON rp.role_id=ur.role_id WHERE ur.user_id=u.id AND ur.is_active=1 AND rp.permission_id=p.id)
              OR EXISTS(SELECT 1 FROM user_permission_overrides allow_override WHERE allow_override.user_id=u.id AND allow_override.permission_id=p.id AND allow_override.decision='ALLOW'))
            AND NOT EXISTS(SELECT 1 FROM user_permission_overrides deny_override WHERE deny_override.user_id=u.id AND deny_override.permission_id=p.id AND deny_override.decision='DENY')),'') AS moduleCodes,
        EXISTS(SELECT 1 FROM user_roles ur INNER JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=u.id AND ur.is_active=1 AND r.code='SUPER_ADMIN') AS isSystemAdmin,
        u.status
      FROM app_users u LEFT JOIN areas a ON a.id=u.primary_area_id {$where}
      ORDER BY u.display_name",$params);
}

function buildAreaDashboard(PDO $pdo, array $area): array
{
    $areaCode=(string)($area['code']??'SIN_AREA');
    $dashboard=[
        'title'=>'Panel de '.($area['name']??'mi área'),
        'metrics'=>[],
        'inventoryByWarehouse'=>safeRows($pdo,"SELECT w.name AS label,w.warehouse_type AS warehouseType,COUNT(DISTINCT a.item_id) AS items,COALESCE(SUM(a.on_hand_qty),0) AS quantity FROM vw_inventory_on_hand a INNER JOIN warehouses w ON w.id=a.warehouse_id GROUP BY w.id,w.name,w.warehouse_type ORDER BY w.name"),
        'criticalMaterials'=>safeRows($pdo,"SELECT i.name AS item,i.sku,i.item_type AS type,COALESCE(SUM(v.available_qty),0) AS available,i.reorder_point,u.name AS uom,CASE WHEN COALESCE(SUM(v.available_qty),0)<=0 THEN 'Sin existencia' ELSE 'Por debajo del punto de reorden' END AS status FROM items i INNER JOIN units_of_measure u ON u.id=i.base_uom_id LEFT JOIN vw_inventory_availability v ON v.item_id=i.id WHERE i.is_active=1 AND i.item_type<>'SERVICE' GROUP BY i.id,i.name,i.sku,i.item_type,i.reorder_point,u.name HAVING i.reorder_point>0 AND available<=i.reorder_point ORDER BY available/i.reorder_point,i.name LIMIT 25"),
        'highFlow'=>safeRows($pdo,"SELECT i.name AS item,i.sku,i.item_type AS type,SUM(ABS(l.quantity_delta)) AS quantity,u.name AS uom FROM inventory_movement_lines l INNER JOIN inventory_movements m ON m.id=l.movement_id INNER JOIN items i ON i.id=l.item_id INNER JOIN units_of_measure u ON u.id=l.uom_id WHERE m.status='POSTED' AND l.quantity_delta<0 AND m.posted_at>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 30 DAY) GROUP BY i.id,i.name,i.sku,i.item_type,u.name ORDER BY quantity DESC LIMIT 15"),
        'planShortages'=>safeRows($pdo,"SELECT i.name AS item,i.sku,i.item_type AS type,SUM(r.net_requirement) AS shortage,MIN(r.requirement_date) AS needDate,u.name AS uom FROM mrp_requirements r INNER JOIN items i ON i.id=r.item_id INNER JOIN units_of_measure u ON u.id=i.base_uom_id WHERE r.mrp_run_id=(SELECT MAX(id) FROM mrp_runs WHERE status='COMPLETED') AND r.status='SHORTAGE' GROUP BY i.id,i.name,i.sku,i.item_type,u.name ORDER BY needDate,shortage DESC LIMIT 30"),
        'forecastCompliance'=>safeRows($pdo,"SELECT i.name AS item,i.sku,i.item_type AS type,SUM(f.forecast_qty) AS forecastQty,COALESCE(stock.available,0) AS availableQty,ROUND(LEAST(100,COALESCE(stock.available,0)/NULLIF(SUM(f.forecast_qty),0)*100),1) AS compliance FROM forecast_versions v INNER JOIN forecast_lines f ON f.forecast_version_id=v.id INNER JOIN items i ON i.id=f.finished_item_id LEFT JOIN (SELECT item_id,SUM(available_qty) AS available FROM vw_inventory_availability GROUP BY item_id) stock ON stock.item_id=i.id WHERE v.is_current=1 AND f.period_start>=DATE_FORMAT(UTC_DATE(),'%Y-%m-01') GROUP BY i.id,i.name,i.sku,i.item_type,stock.available ORDER BY compliance,i.name LIMIT 25"),
    ];
    if($areaCode==='COMPRAS'){
        $dashboard['metrics']=[
            ['label'=>'Llegadas próximas','value'=>safeScalar($pdo,"SELECT COUNT(*) FROM inbound_appointments WHERE scheduled_start BETWEEN UTC_TIMESTAMP() AND DATE_ADD(UTC_TIMESTAMP(),INTERVAL 7 DAY) AND status NOT IN ('COMPLETED','CANCELLED')"),'note'=>'Próximos siete días','tone'=>''],
            ['label'=>'Citas por confirmar','value'=>safeScalar($pdo,"SELECT COUNT(*) FROM inbound_appointments WHERE status IN ('PLANNED','SENT') AND scheduled_start>=UTC_TIMESTAMP()"),'note'=>'Requieren seguimiento','tone'=>'warning'],
            ['label'=>'Necesidades por comprar','value'=>safeScalar($pdo,"SELECT COUNT(*) FROM mrp_requirements WHERE status='SHORTAGE'"),'note'=>'Según el último cálculo','tone'=>'danger'],
            ['label'=>'Proveedores activos','value'=>safeScalar($pdo,"SELECT COUNT(*) FROM suppliers WHERE is_active=1"),'note'=>'Catálogo vigente','tone'=>''],
        ];
    }elseif($areaCode==='MANTENIMIENTO'){
        $dashboard['metrics']=[
            ['label'=>'Solicitudes abiertas','value'=>safeScalar($pdo,"SELECT COUNT(*) FROM maintenance_work_requests WHERE status NOT IN ('VERIFIED','CANCELLED')"),'note'=>'Pendientes de cierre','tone'=>'warning'],
            ['label'=>'Tareas en proceso','value'=>safeScalar($pdo,"SELECT COUNT(*) FROM maintenance_work_requests WHERE status='IN_PROGRESS'"),'note'=>'Con técnicos trabajando','tone'=>''],
            ['label'=>'Tareas críticas','value'=>safeScalar($pdo,"SELECT COUNT(*) FROM maintenance_work_requests WHERE priority_code='CRITICAL' AND status NOT IN ('VERIFIED','CANCELLED')"),'note'=>'Atención inmediata','tone'=>'danger'],
            ['label'=>'Horas registradas','value'=>safeScalar($pdo,"SELECT COALESCE(SUM(actual_hours),0) FROM maintenance_work_assignments"),'note'=>'Horas de intervención','tone'=>''],
        ];
    }elseif($areaCode==='CALIDAD'){
        $dashboard['metrics']=[
            ['label'=>'Solicitudes pendientes','value'=>safeScalar($pdo,"SELECT COUNT(*) FROM quality_requests WHERE status NOT IN ('COMPLETED','CANCELLED')"),'note'=>'Pendientes de dictamen','tone'=>'warning'],
            ['label'=>'Lotes bloqueados','value'=>safeScalar($pdo,"SELECT COUNT(*) FROM inventory_lots WHERE lot_status='BLOCKED'"),'note'=>'No disponibles para consumo','tone'=>'danger'],
            ['label'=>'Aprobados este mes','value'=>safeScalar($pdo,"SELECT COUNT(*) FROM quality_requests WHERE disposition='APPROVED' AND completed_at>=DATE_FORMAT(UTC_DATE(),'%Y-%m-01')"),'note'=>'Liberados por Calidad','tone'=>''],
            ['label'=>'Rechazados este mes','value'=>safeScalar($pdo,"SELECT COUNT(*) FROM quality_requests WHERE disposition='REJECTED' AND completed_at>=DATE_FORMAT(UTC_DATE(),'%Y-%m-01')"),'note'=>'Requieren seguimiento','tone'=>'danger'],
        ];
    }elseif(in_array($areaCode,['ENVASADO','PRODUCCION'],true)){
        $dashboard['metrics']=[
            ['label'=>'Órdenes abiertas','value'=>safeScalar($pdo,"SELECT COUNT(*) FROM production_orders WHERE status NOT IN ('COMPLETED','CLOSED','CANCELLED')"),'note'=>'Pendientes de terminar','tone'=>''],
            ['label'=>'Órdenes con faltantes','value'=>safeScalar($pdo,"SELECT COUNT(*) FROM production_orders WHERE status IN ('MATERIAL_CHECK','ON_HOLD')"),'note'=>'Material incompleto','tone'=>'danger'],
            ['label'=>'Listas activas','value'=>safeScalar($pdo,"SELECT COUNT(*) FROM bom_versions WHERE status='ACTIVE'"),'note'=>'Listas de materiales vigentes','tone'=>''],
            ['label'=>'Terminaciones de hoy','value'=>safeScalar($pdo,"SELECT COUNT(*) FROM production_completions WHERE completed_at>=UTC_DATE()"),'note'=>'Entradas a producto terminado','tone'=>''],
        ];
    }elseif($areaCode==='EXTRACCION'){
        $dashboard['metrics']=[
            ['label'=>'Procesos abiertos','value'=>safeScalar($pdo,"SELECT COUNT(*) FROM process_batches WHERE process_type='EXTRACTION' AND status NOT IN ('COMPLETED','CANCELLED')"),'note'=>'Lotes en proceso','tone'=>''],
            ['label'=>'Debajo de meta','value'=>safeScalar($pdo,"SELECT COUNT(*) FROM extraction_runs WHERE beans_count/operating_hours<target_beans_hour"),'note'=>'Menos de 13 contenedores por hora','tone'=>'warning'],
            ['label'=>'Pendientes de Calidad','value'=>safeScalar($pdo,"SELECT COUNT(*) FROM quality_requests WHERE request_type='IN_PROCESS' AND status NOT IN ('COMPLETED','CANCELLED')"),'note'=>'Muestras sin dictamen','tone'=>'warning'],
            ['label'=>'Procesos de hoy','value'=>safeScalar($pdo,"SELECT COUNT(*) FROM process_batches WHERE process_type='EXTRACTION' AND started_at>=UTC_DATE()"),'note'=>'Lotes alimentados','tone'=>''],
        ];
    }else{
        $dashboard['metrics']=[
            ['label'=>'Productos con existencia','value'=>safeScalar($pdo,"SELECT COUNT(DISTINCT item_id) FROM vw_inventory_on_hand"),'note'=>'Inventario contabilizado','tone'=>''],
            ['label'=>'Materiales críticos','value'=>count($dashboard['criticalMaterials']),'note'=>'En punto de reorden','tone'=>'danger'],
            ['label'=>'Pendientes de Calidad','value'=>safeScalar($pdo,"SELECT COUNT(*) FROM quality_requests WHERE status NOT IN ('COMPLETED','CANCELLED')"),'note'=>'Esperan dictamen','tone'=>'warning'],
            ['label'=>'Órdenes en riesgo','value'=>safeScalar($pdo,"SELECT COUNT(*) FROM production_orders WHERE status IN ('MATERIAL_CHECK','ON_HOLD')"),'note'=>'Posible incumplimiento','tone'=>'danger'],
        ];
    }
    return $dashboard;
}

function buildPurchaseDashboard(PDO $pdo): array
{
    return [
        'upcoming'=>safeRows($pdo,"SELECT a.appointment_number AS id,DATE_FORMAT(a.scheduled_start,'%d %b %Y · %H:%i') AS scheduled,COALESCE(s.trade_name,s.legal_name) AS supplier,a.notes AS material,a.status,COALESCE(a.delay_minutes,0) AS delayMinutes FROM inbound_appointments a INNER JOIN suppliers s ON s.id=a.supplier_id WHERE a.scheduled_start>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 1 DAY) AND a.status NOT IN ('COMPLETED','CANCELLED') ORDER BY a.scheduled_start LIMIT 100"),
        'needs'=>safeRows($pdo,"SELECT i.name AS item,i.sku,r.net_requirement AS shortage,r.requirement_date AS needDate,u.name AS uom,COALESCE(s.trade_name,s.legal_name,'Proveedor por definir') AS supplier FROM mrp_requirements r INNER JOIN items i ON i.id=r.item_id INNER JOIN units_of_measure u ON u.id=i.base_uom_id LEFT JOIN supplier_items si ON si.item_id=i.id AND si.is_preferred=1 LEFT JOIN suppliers s ON s.id=si.supplier_id WHERE r.status='SHORTAGE' AND r.mrp_run_id=(SELECT MAX(id) FROM mrp_runs WHERE status='COMPLETED') ORDER BY r.requirement_date,i.name LIMIT 200"),
    ];
}

function buildMaintenanceWork(PDO $pdo, array $user): array
{
    [$filter,$params]=maintenanceVisibility($pdo,$user,'r');
    $params['current_user']=$user['id'];
    return safeRows($pdo,"SELECT r.id,r.request_number AS requestNumber,r.title,r.description,COALESCE(a.asset_name,'Sin equipo asociado') AS asset,ar.name AS requestingArea,r.location_description AS location,r.requested_materials AS materials,r.priority_code AS priority,DATE_FORMAT(r.needed_at,'%d %b %Y · %H:%i') AS needed,r.status,COALESCE(work.technicians,'Sin técnicos asignados') AS technicians,COALESCE(work.estimated_hours,0) AS estimatedHours,COALESCE(work.actual_hours,0) AS actualHours,COALESCE(evidence.evidence_count,0) AS evidenceCount,EXISTS(SELECT 1 FROM maintenance_work_assignments own_assignment WHERE own_assignment.work_request_id=r.id AND own_assignment.technician_user_id=:current_user AND own_assignment.assignment_status<>'CANCELLED') AS canRespond FROM maintenance_work_requests r INNER JOIN areas ar ON ar.id=r.requesting_area_id LEFT JOIN maintenance_assets a ON a.id=r.asset_id LEFT JOIN (SELECT wa.work_request_id,GROUP_CONCAT(u.display_name ORDER BY u.display_name SEPARATOR ', ') AS technicians,SUM(wa.estimated_hours) AS estimated_hours,SUM(wa.actual_hours) AS actual_hours FROM maintenance_work_assignments wa INNER JOIN app_users u ON u.id=wa.technician_user_id WHERE wa.assignment_status<>'CANCELLED' GROUP BY wa.work_request_id) work ON work.work_request_id=r.id LEFT JOIN (SELECT CAST(entity_id AS UNSIGNED) AS work_request_id,COUNT(*) AS evidence_count FROM file_attachments WHERE entity_type='maintenance_work_request' GROUP BY CAST(entity_id AS UNSIGNED)) evidence ON evidence.work_request_id=r.id {$filter} ORDER BY FIELD(r.priority_code,'CRITICAL','HIGH','NORMAL','LOW'),r.needed_at",$params);
}

function buildMaintenanceUpdates(PDO $pdo, array $user): array
{
    [$filter,$params]=maintenanceVisibility($pdo,$user,'r');
    return safeRows($pdo,"SELECT u.work_request_id AS requestId,u.status,u.hours_reported AS hours,u.observations,COALESCE(a.display_name,'Sistema') AS user,DATE_FORMAT(u.created_at,'%d %b %Y · %H:%i') AS createdAt FROM maintenance_work_updates u INNER JOIN maintenance_work_requests r ON r.id=u.work_request_id LEFT JOIN app_users a ON a.id=u.updated_by {$filter} ORDER BY u.created_at DESC LIMIT 2000",$params);
}

function buildMaintenanceEvidence(PDO $pdo, array $user): array
{
    [$filter,$params]=maintenanceVisibility($pdo,$user,'r');
    return safeRows($pdo,"SELECT f.id,CAST(f.entity_id AS UNSIGNED) AS requestId,f.file_name AS fileName,f.mime_type AS mimeType,COALESCE(u.display_name,'Sistema') AS uploadedBy,DATE_FORMAT(f.uploaded_at,'%d %b %Y · %H:%i') AS uploadedAt FROM file_attachments f INNER JOIN maintenance_work_requests r ON r.id=CAST(f.entity_id AS UNSIGNED) LEFT JOIN app_users u ON u.id=f.uploaded_by {$filter} AND f.entity_type='maintenance_work_request' ORDER BY f.uploaded_at DESC LIMIT 2000",$params);
}

function buildInventoryAuditSchedules(PDO $pdo): array
{
    return safeRows($pdo,"SELECT s.id,s.schedule_name AS name,w.name AS warehouse,w.warehouse_type AS warehouseType,s.weekday_codes AS weekdays,TIME_FORMAT(s.start_time,'%H:%i') AS startTime,s.count_type AS countType,s.scope_description AS scope,s.notes,s.is_active AS isActive FROM inventory_audit_schedules s INNER JOIN warehouses w ON w.id=s.warehouse_id WHERE s.is_active=1 ORDER BY w.name,s.start_time,s.schedule_name");
}

function buildInventoryAuditDetails(PDO $pdo): array
{
    return safeRows($pdo,"SELECT c.count_number AS countNumber,DATE_FORMAT(COALESCE(c.completed_at,c.created_at),'%d %b %Y · %H:%i') AS auditDate,w.name AS warehouse,w.warehouse_type AS warehouseType,i.name AS item,i.sku,COALESCE(l.lot_code,'Sin lote') AS lot,wl.name AS location,cl.system_qty AS systemQuantity,cl.final_count_qty AS countedQuantity,cl.variance_qty AS difference,uom.name AS uom,COALESCE(cl.notes,'Sin observaciones') AS observations,COALESCE(u.display_name,'Sistema') AS countedBy FROM inventory_count_lines cl INNER JOIN inventory_counts c ON c.id=cl.inventory_count_id INNER JOIN warehouses w ON w.id=c.warehouse_id INNER JOIN items i ON i.id=cl.item_id INNER JOIN units_of_measure uom ON uom.id=i.base_uom_id INNER JOIN warehouse_locations wl ON wl.id=cl.location_id LEFT JOIN inventory_lots l ON l.id=cl.inventory_lot_id LEFT JOIN app_users u ON u.id=cl.counted_by WHERE cl.final_count_qty IS NOT NULL ORDER BY c.created_at DESC,ABS(cl.variance_qty) DESC LIMIT 3000");
}

function createInventoryAuditSchedule(PDO $pdo, array $user, array $payload): array
{
    requireArea($pdo,$user,['ALMACEN']);
    $warehouse=findOne($pdo,"SELECT id,name,warehouse_type FROM warehouses WHERE id=:id AND is_active=1",['id'=>(int)($payload['warehouse_id']??0)],'Selecciona un almacén válido.');$module=['RAW_MATERIAL'=>'WAREHOUSE_RAW','PACKAGING'=>'WAREHOUSE_PACKAGING','SPARE_PARTS'=>'WAREHOUSE_SPARES','FINISHED_GOODS'=>'WAREHOUSE_FINISHED'][$warehouse['warehouse_type']]??'COUNTS';requireAnyPermissionV14($pdo,(int)$user['id'],[$module,'COUNTS'],'CREATE');$rawDays=$payload['weekday_codes']??[];if(!is_array($rawDays))$rawDays=explode(',',(string)$rawDays);$allowed=['MON','TUE','WED','THU','FRI','SAT','SUN'];$days=array_values(array_unique(array_filter(array_map(fn($day)=>strtoupper(trim((string)$day)),$rawDays),fn($day)=>in_array($day,$allowed,true))));if(!$days)failRequest('Selecciona al menos un día de la semana.',422);$time=trim((string)($payload['start_time']??''));if(!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/',$time))failRequest('La hora programada no es válida.',422);$type=strtoupper((string)($payload['count_type']??'CYCLE'));if(!in_array($type,['CYCLE','FULL','SPOT','QUALITY_HOLD'],true))failRequest('El tipo de auditoría no es válido.',422);
    $pdo->prepare("INSERT INTO inventory_audit_schedules (schedule_name,warehouse_id,weekday_codes,start_time,count_type,scope_description,notes,is_active,created_by) VALUES (:name,:warehouse,:days,:time,:type,:scope,:notes,1,:user)")->execute(['name'=>requiredString($payload,'schedule_name','el nombre del programa',160),'warehouse'=>$warehouse['id'],'days'=>implode(',',$days),'time'=>$time.':00','type'=>$type,'scope'=>requiredString($payload,'scope_description','el alcance de la auditoría',255),'notes'=>optionalString($payload,'notes',1000),'user'=>$user['id']]);$id=(int)$pdo->lastInsertId();writeAudit($pdo,(int)$user['id'],'CREATE','inventory_audit_schedule',$id,['warehouse'=>$warehouse['name'],'weekdays'=>$days,'time'=>$time]);return ['id'=>$id,'warehouse'=>$warehouse['name'],'weekdays'=>$days];
}

function createArea(PDO $pdo, array $user, array $payload): array
{
    if(!isSuperAdmin($pdo,(int)$user['id'])) failRequest('Solo el administrador del sistema puede crear áreas.',403);
    $name=requiredString($payload,'area_name','el nombre del área',120);$code=uniqueGeneratedCode($pdo,'areas','code',$name);
    $pdo->prepare("INSERT INTO areas (code,name,is_active) VALUES (:code,:name,1)")->execute(['code'=>$code,'name'=>$name]);
    $id=(int)$pdo->lastInsertId();writeAudit($pdo,(int)$user['id'],'CREATE','area',$id,['name'=>$name]);return ['id'=>$id,'name'=>$name];
}

function createRole(PDO $pdo, array $user, array $payload): array
{
    if(!isSuperAdmin($pdo,(int)$user['id'])) failRequest('Solo el administrador del sistema puede crear roles.',403);
    $name=requiredString($payload,'role_name','el nombre del rol',100);$code=uniqueGeneratedCode($pdo,'roles','code',$name);
    $profile=(string)($payload['permission_profile']??'VIEWER');$profiles=['VIEWER'=>['VIEW','EXPORT'],'OPERATOR'=>['VIEW','CREATE','UPDATE','POST','EXPORT'],'APPROVER'=>['VIEW','APPROVE','REJECT','EXPORT'],'MANAGER'=>['VIEW','CREATE','UPDATE','APPROVE','REJECT','POST','EXPORT']];
    if(!isset($profiles[$profile])) failRequest('El nivel de permisos no es válido.',422);
    $modules=$payload['module_codes']??[];if(!is_array($modules))$modules=explode(',',(string)$modules);$modules=array_values(array_unique(array_filter(array_map(fn($x)=>strtoupper(trim((string)$x)),$modules))));if(!$modules)failRequest('Selecciona al menos un módulo.',422);
    $pdo->beginTransaction();$pdo->prepare("INSERT INTO roles (code,name,description,is_system,is_active) VALUES (:code,:name,:description,0,1)")->execute(['code'=>$code,'name'=>$name,'description'=>optionalString($payload,'description',255)]);$id=(int)$pdo->lastInsertId();
    $grant=$pdo->prepare("INSERT IGNORE INTO role_permissions (role_id,permission_id,granted_by) SELECT :role,p.id,:user FROM permissions p INNER JOIN app_modules m ON m.id=p.module_id WHERE m.code=:module AND p.action_code=:action");foreach($modules as $module){foreach($profiles[$profile] as $action)$grant->execute(['role'=>$id,'user'=>$user['id'],'module'=>$module,'action'=>$action]);}
    writeAudit($pdo,(int)$user['id'],'CREATE','role',$id,['name'=>$name,'modules'=>$modules,'profile'=>$profile]);$pdo->commit();return ['id'=>$id,'name'=>$name];
}

function createTechnician(PDO $pdo, array $user, array $payload): array
{
    $maintenanceArea=findOne($pdo,"SELECT id FROM areas WHERE code='MANTENIMIENTO' AND is_active=1",[],'No existe el área de Mantenimiento.');
    if(!isSuperAdmin($pdo,(int)$user['id']) && ((int)$user['primary_area_id']!==(int)$maintenanceArea['id'] || !isAreaLeader($pdo,(int)$user['id']))) failRequest('Solo el administrador de Mantenimiento puede registrar técnicos.',403);
    $payload['area_id']=$maintenanceArea['id'];$payload['role_code']='TECHNICIAN';$payload['module_codes']=['MAINTENANCE'];
