function uniqueGeneratedCode(PDO $pdo, string $table, string $column, string $name): string
{
    $ascii=iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$name)?:$name;$base=strtoupper(trim((string)preg_replace('/[^A-Za-z0-9]+/','_',$ascii),'_'));$base=substr($base?:'REGISTRO',0,32);$code=$base;$i=2;
    while((float)safeScalar($pdo,"SELECT COUNT(*) FROM {$table} WHERE {$column}=:code",['code'=>$code])>0){$suffix='_'.$i++;$code=substr($base,0,40-strlen($suffix)).$suffix;}
    return $code;
}

