ntLine,'item'=>$resolved['item_id'],'lot'=>$resolved['lot_id'],'warehouse'=>$warehouse['id'],'location'=>$resolved['location_id'],'uom'=>$resolved['uom_id'],'qty'=>$delta,'notes'=>'Diferencia de auditoría: '.$resolved['item_name']]);}}
