function resolveInventoryCaptureLine(PDO $pdo, array $warehouse, array $line, int $userId, string $date, bool $allowCreateLot): array
{
    $item=findOne($pdo,"SELECT i.id,i.name,i.item_type,i.base_uom_id,i.lot_controlled,i.quality_required FROM items i WHERE i.id=:id AND i.is_active=1",['id'=>(int)($line['item_id']??0)],'Selecciona un producto o material válido.');$allowed=['RAW_MATERIAL'=>['RAW_FRUIT','RAW_OTHER','BULK_OIL'],'PACKAGING'=>['PACKAGING','CONSUMABLE'],'SPARE_PARTS'=>['SPARE_PART'],'FINISHED_GOODS'=>['FINISHED_GOOD']];if(isset($warehouse['warehouse_type'])&&!in_array($item['item_type'],$allowed[$warehouse['warehouse_type']]??[],true))failRequest('El producto o material no pertenece al almacén seleccionado.',422);$location=findOne($pdo,"SELECT id,location_type,is_blocked FROM warehouse_locations WHERE id=:id AND warehouse_id=:warehouse AND is_active=1",['id'=>(int)($line['location_id']??0),'warehouse'=>$warehouse['id']],'La ubicación no pertenece al almacén seleccionado.');$quantity=filter_var($line['quantity']??null,FILTER_VALIDATE_FLOAT);if($quantity===false||$quantity<0)failRequest('La cantidad física debe ser igual o mayor que cero.',422);$quality=strtoupper(trim((string)($line['quality_status']??'APPROVED')));if(!in_array($quality,['PENDING','APPROVED','CONDITIONAL','REJECTED'],true))failRequest('El estado de Calidad no es válido.',422);if((int)$location['is_blocked']===1&&!in_array($location['location_type'],['QUALITY_HOLD','REJECTED'],true))failRequest('La ubicación seleccionada está bloqueada.',409);if($quality==='REJECTED'&&$location['location_type']!=='REJECTED')failRequest('El producto rechazado debe capturarse en la zona de rechazados.',422);if($quality==='PENDING'&&!in_array($location['location_type'],['RECEIVING','QUALITY_HOLD'],true))failRequest('El producto pendiente de Calidad debe quedar en recepción temporal o pendiente de liberación.',422);if(in_array($quality,['APPROVED','CONDITIONAL'],true)&&!in_array($location['location_type'],['STORAGE','PICKING'],true))failRequest('El producto liberado debe quedar en existencia disponible o preparación de surtido.',422);$lotId=null;$lotCode=trim((string)($line['lot_code']??''));
    if((int)$item['lot_controlled']===1){if($lotCode==='')failRequest('Indica el lote de '.$item['name'].'.',422);$statement=$pdo->prepare("SELECT id FROM inventory_lots WHERE item_id=:item AND lot_code=:lot LIMIT 1");$statement->execute(['item'=>$item['id'],'lot'=>$lotCode]);$lotId=$statement->fetchColumn();if(!$lotId){if(!$allowCreateLot && $quantity<=0)failRequest('El lote indicado no existe.',422);$lotStatus=in_array($quality,['PENDING','REJECTED'],true)?'BLOCKED':'OPEN';$pdo->prepare("INSERT INTO inventory_lots (item_id,lot_code,received_date,quality_status,lot_status,created_by) VALUES (:item,:lot,:date,:quality,:status,:user)")->execute(['item'=>$item['id'],'lot'=>$lotCode,'date'=>$date,'quality'=>$quality,'status'=>$lotStatus,'user'=>$userId]);$lotId=(int)$pdo->lastInsertId();}}
    return ['item_id'=>(int)$item['id'],'item_name'=>$item['name'],'uom_id'=>(int)$item['base_uom_id'],'location_id'=>(int)$location['id'],'lot_id'=>$lotId===null?null:(int)$lotId,'quantity'=>(float)$quantity,'quality_status'=>(int)$item['lot_controlled']===1?$quality:null,'notes'=>mb_substr(trim((string)($line['notes']??'')),0,500)?:null];
}

function validDate(string $value): string
{
    $date=DateTimeImmutable::createFromFormat('!Y-m-d',$value,new DateTimeZone('America/Mexico_City'));if(!$date||$date->format('Y-m-d')!==$value)failRequest('La fecha no es válida.',422);return $value;
}

function importForecast(PDO $pdo, array $user, array $payload): array
