    requirePermission($pdo,(int)$user['id'],'FORECAST','CREATE');$rows=$payload['rows']??[];if(!is_array($rows)||!$rows||count($rows)>20000)failRequest('El archivo debe contener entre 1 y 20,000 registros.',422);$year=(int)($payload['fiscal_year']??0);if($year<2020||$year>2100)failRequest('El año del Forecast no es válido.',422);$normalized=[];$missing=[];$invalid=[];
    $findItem=$pdo->prepare("SELECT id,name FROM items WHERE sku=:code AND item_type='FINISHED_GOOD' AND is_active=1 LIMIT 1");$findCustomer=$pdo->prepare("SELECT id FROM customers WHERE customer_code=:customer_code OR legal_name=:legal_name OR trade_name=:trade_name LIMIT 1");
    foreach($rows as $index=>$row){if(!is_array($row))continue;$code=strtoupper(trim((string)($row['product_code']??'')));$period=(string)($row['period_start']??'');$qty=filter_var($row['quantity']??null,FILTER_VALIDATE_FLOAT);if($code===''||!preg_match('/^\d{4}-\d{2}-01$/',$period)||$qty===false||(float)$qty<0){$invalid[]=$index+1;continue;}$findItem->execute(['code'=>$code]);$item=$findItem->fetch();if(!$item){$missing[$code]=true;continue;}$customerId=null;$customer=trim((string)($row['customer']??''));if($customer!==''){$findCustomer->execute(['customer_code'=>$customer,'legal_name'=>$customer,'trade_name'=>$customer]);$customerId=$findCustomer->fetchColumn()?:null;}$key=$item['id'].'|'.($customerId??0).'|'.$period;if(!isset($normalized[$key]))$normalized[$key]=['item'=>(int)$item['id'],'customer'=>$customerId===null?null:(int)$customerId,'period'=>$period,'quantity'=>0,'source'=>$code.'-'.$period];$normalized[$key]['quantity']+=(float)$qty;}
    if($missing||$invalid)return ['imported'=>false,'matchedRows'=>count($normalized),'missingProductCodes'=>array_keys($missing),'invalidRows'=>array_slice($invalid,0,100)];
    $planCode='FORECAST-'.$year;$planName=trim((string)($payload['plan_name']??''))?:'Plan anual '.$year;$versionName=requiredString($payload,'version_name','el nombre de la versión',120);$reason=requiredString($payload,'change_reason','el motivo de la importación',1000);
    $pdo->beginTransaction();try{$pdo->prepare("INSERT INTO forecast_plans (plan_code,name,fiscal_year,status,created_by) VALUES (:code,:name,:year,'ACTIVE',:user) ON DUPLICATE KEY UPDATE name=VALUES(name)")->execute(['code'=>$planCode,'name'=>$planName,'year'=>$year,'user'=>$user['id']]);$plan=findOne($pdo,"SELECT id FROM forecast_plans WHERE plan_code=:code FOR UPDATE",['code'=>$planCode],'No se pudo crear el plan.');$versionNo=(int)safeScalar($pdo,"SELECT COALESCE(MAX(version_no),0)+1 FROM forecast_versions WHERE forecast_plan_id=:plan",['plan'=>$plan['id']]);$type=$versionNo===1?'ORIGINAL':'REVISION';$pdo->prepare("UPDATE forecast_versions SET is_current=0 WHERE forecast_plan_id=:plan AND is_current=1")->execute(['plan'=>$plan['id']]);$pdo->prepare("INSERT INTO forecast_versions (forecast_plan_id,version_no,version_type,version_name,source_file_name,source_file_hash,change_reason,is_current,approved_by,approved_at,imported_by) VALUES (:plan,:version,:type,:name,:file,:hash,:reason,1,:approved_user,UTC_TIMESTAMP(6),:imported_user)")->execute(['plan'=>$plan['id'],'version'=>$versionNo,'type'=>$type,'name'=>$versionName,'file'=>mb_substr((string)($payload['source_file_name']??''),0,255)?:null,'hash'=>preg_match('/^[a-f0-9]{64}$/',(string)($payload['source_file_hash']??''))?(string)$payload['source_file_hash']:null,'reason'=>$reason,'approved_user'=>$user['id'],'imported_user'=>$user['id']]);$versionId=(int)$pdo->lastInsertId();$insert=$pdo->prepare("INSERT INTO forecast_lines (forecast_version_id,customer_id,finished_item_id,period_start,forecast_qty,source_row_key) VALUES (:version,:customer,:item,:period,:quantity,:source)");foreach($normalized as $row)$insert->execute(['version'=>$versionId,'customer'=>$row['customer'],'item'=>$row['item'],'period'=>$row['period'],'quantity'=>$row['quantity'],'source'=>$row['source']]);if($versionNo>1){$planningArea=safeScalar($pdo,"SELECT id FROM areas WHERE code='PLANEACION' LIMIT 1");$pdo->prepare("INSERT IGNORE INTO alerts (alert_type,severity,title,message,entity_type,entity_id,area_id,status,deduplication_key) VALUES ('FORECAST_CHANGE','WARNING',:title,:message,'forecast_version',:entity,:area,'OPEN',:dedup)")->execute(['title'=>'Nueva revisión del Forecast','message'=>"Se importó la versión {$versionNo} de {$planCode}. Motivo: {$reason}",'entity'=>(string)$versionId,'area'=>$planningArea?:null,'dedup'=>'FORECAST_VERSION_'.$versionId]);}$mrp=recalculateMrpForForecast($pdo,$versionId,(int)$user['id']);writeAudit($pdo,(int)$user['id'],'CREATE','forecast_version',$versionId,['plan'=>$planCode,'version'=>$versionNo,'rows'=>count($normalized),'mrp_run'=>$mrp['runNumber']],$reason);$pdo->commit();return ['imported'=>true,'plan'=>$planCode,'version'=>$versionNo,'type'=>$type,'rows'=>count($normalized),'mrp'=>$mrp];}catch(Throwable $error){if($pdo->inTransaction())$pdo->rollBack();throw $error;}
}

function createBomComponent(PDO $pdo, array $user, array $payload): array
{
    requireArea($pdo,$user,['ENVASADO','PRODUCCION']);
    requireAnyPermissionV14($pdo,(int)$user['id'],['FILLING','PRODUCTION'],'CREATE');
    $output=findOne($pdo,"SELECT id,sku,name,base_uom_id FROM items WHERE id=:id AND item_type='FINISHED_GOOD' AND is_active=1",['id'=>(int)($payload['finished_item_id']??0)],'Selecciona un producto terminado válido.');
    $component=findOne($pdo,"SELECT id,sku,name,base_uom_id FROM items WHERE id=:id AND item_type<>'FINISHED_GOOD' AND item_type<>'SERVICE' AND is_active=1",['id'=>(int)($payload['component_item_id']??0)],'Selecciona un material o materia prima válido.');
    $outputQty=filter_var($payload['output_quantity']??null,FILTER_VALIDATE_FLOAT);$componentQty=filter_var($payload['component_quantity']??null,FILTER_VALIDATE_FLOAT);$scrap=filter_var($payload['scrap_percent']??0,FILTER_VALIDATE_FLOAT);
    if($outputQty===false||$outputQty<=0||$componentQty===false||$componentQty<=0||$scrap===false||$scrap<0||$scrap>100)failRequest('Las cantidades deben ser mayores que cero y la merma debe estar entre cero y cien.',422);
    $pdo->beginTransaction();
    try{
        $code='BOM-'.substr((string)$output['sku'],0,44).'-'.substr(hash('sha256',(string)$output['id']),0,8);$pdo->prepare("INSERT INTO bills_of_material (bom_code,output_item_id,name,is_active,created_by) VALUES (:code,:item,:name,1,:user) ON DUPLICATE KEY UPDATE name=VALUES(name),is_active=1")->execute(['code'=>$code,'item'=>$output['id'],'name'=>'Lista de materiales de '.$output['name'],'user'=>$user['id']]);$bom=findOne($pdo,"SELECT id FROM bills_of_material WHERE bom_code=:code FOR UPDATE",['code'=>$code],'No se pudo preparar la lista de materiales.');
        $versionRows=safeRows($pdo,"SELECT id FROM bom_versions WHERE bom_id=:bom AND status='ACTIVE' ORDER BY version_no DESC LIMIT 1",['bom'=>$bom['id']]);
        if($versionRows){$versionId=(int)$versionRows[0]['id'];$pdo->prepare("UPDATE bom_versions SET output_qty=:quantity,output_uom_id=:uom WHERE id=:id")->execute(['quantity'=>$outputQty,'uom'=>$output['base_uom_id'],'id'=>$versionId]);}
        else{$next=(int)safeScalar($pdo,"SELECT COALESCE(MAX(version_no),0)+1 FROM bom_versions WHERE bom_id=:bom",['bom'=>$bom['id']]);$pdo->prepare("INSERT INTO bom_versions (bom_id,version_no,output_qty,output_uom_id,effective_from,status,approved_by,approved_at) VALUES (:bom,:version,:quantity,:uom,UTC_DATE(),'ACTIVE',:user,UTC_TIMESTAMP(6))")->execute(['bom'=>$bom['id'],'version'=>$next,'quantity'=>$outputQty,'uom'=>$output['base_uom_id'],'user'=>$user['id']]);$versionId=(int)$pdo->lastInsertId();}
        $line=(int)safeScalar($pdo,"SELECT COALESCE(MAX(line_no),0)+1 FROM bom_components WHERE bom_version_id=:version",['version'=>$versionId]);$pdo->prepare("INSERT INTO bom_components (bom_version_id,line_no,component_item_id,component_uom_id,qty_per_output,scrap_pct,is_optional) VALUES (:version,:line,:component,:uom,:quantity,:scrap,0) ON DUPLICATE KEY UPDATE component_uom_id=VALUES(component_uom_id),qty_per_output=VALUES(qty_per_output),scrap_pct=VALUES(scrap_pct),is_optional=0")->execute(['version'=>$versionId,'line'=>$line,'component'=>$component['id'],'uom'=>$component['base_uom_id'],'quantity'=>$componentQty,'scrap'=>$scrap]);
        $runs=recalculateCurrentForecasts($pdo,(int)$user['id']);writeAudit($pdo,(int)$user['id'],'UPDATE','bill_of_material',$bom['id'],['finished_product'=>$output['sku'],'component'=>$component['sku'],'quantity'=>$componentQty,'output_quantity'=>$outputQty]);$pdo->commit();return ['id'=>(int)$bom['id'],'product'=>$output['name'],'component'=>$component['name'],'mrpRuns'=>$runs];
    }catch(Throwable $error){if($pdo->inTransaction())$pdo->rollBack();throw $error;}
}

function recalculateCurrentForecasts(PDO $pdo, int $userId): int
{
    $versions=safeRows($pdo,"SELECT id FROM forecast_versions WHERE is_current=1 ORDER BY id");foreach($versions as $version)recalculateMrpForForecast($pdo,(int)$version['id'],$userId);return count($versions);
}

function recalculateMrpForForecast(PDO $pdo, int $forecastVersionId, int $userId): array
{
    $horizon=findOne($pdo,"SELECT MIN(period_start) AS start_date,LAST_DAY(MAX(period_start)) AS end_date FROM forecast_lines WHERE forecast_version_id=:version",['version'=>$forecastVersionId],'El Forecast no contiene periodos válidos.');
    $insertRun=$pdo->prepare("INSERT INTO mrp_runs (run_number,forecast_version_id,horizon_start,horizon_end,status,parameters_json,started_at,created_by) VALUES (:number,:version,:start,:end,'RUNNING',JSON_OBJECT('source','automatico'),UTC_TIMESTAMP(6),:user)");$insertRun->execute(['number'=>provisionalNumber('MRP'),'version'=>$forecastVersionId,'start'=>$horizon['start_date'],'end'=>$horizon['end_date'],'user'=>$userId]);$runId=(int)$pdo->lastInsertId();$runNumber=finalNumber('MRP',$runId);$pdo->prepare("UPDATE mrp_runs SET run_number=:number WHERE id=:id")->execute(['number'=>$runNumber,'id'=>$runId]);
    $grossRows=safeRows($pdo,"SELECT bc.component_item_id AS item_id,fl.period_start,SUM((fl.forecast_qty/bv.output_qty)*bc.qty_per_output*(1+(bc.scrap_pct/100))) AS gross_requirement FROM forecast_lines fl INNER JOIN bills_of_material bom ON bom.output_item_id=fl.finished_item_id AND bom.is_active=1 INNER JOIN bom_versions bv ON bv.bom_id=bom.id AND bv.status='ACTIVE' AND bv.effective_from<=fl.period_start AND (bv.effective_to IS NULL OR bv.effective_to>=fl.period_start) INNER JOIN bom_components bc ON bc.bom_version_id=bv.id WHERE fl.forecast_version_id=:version GROUP BY bc.component_item_id,fl.period_start ORDER BY bc.component_item_id,fl.period_start",['version'=>$forecastVersionId]);
    $missing=safeRows($pdo,"SELECT DISTINCT i.sku,i.name FROM forecast_lines fl INNER JOIN items i ON i.id=fl.finished_item_id WHERE fl.forecast_version_id=:version AND NOT EXISTS(SELECT 1 FROM bills_of_material bom INNER JOIN bom_versions bv ON bv.bom_id=bom.id AND bv.status='ACTIVE' WHERE bom.output_item_id=fl.finished_item_id AND bom.is_active=1 AND bv.effective_from<=fl.period_start AND (bv.effective_to IS NULL OR bv.effective_to>=fl.period_start)) ORDER BY i.name",['version'=>$forecastVersionId]);
    $inventory=safeRows($pdo,"SELECT i.id,i.minimum_stock,COALESCE(si.lead_time_days,i.lead_time_days) AS lead_days,COALESCE(SUM(v.on_hand_qty),0) AS on_hand,COALESCE(SUM(v.reserved_qty),0) AS reserved FROM items i LEFT JOIN vw_inventory_availability v ON v.item_id=i.id LEFT JOIN (SELECT item_id,MAX(lead_time_days) AS lead_time_days FROM supplier_items WHERE is_active=1 AND is_preferred=1 GROUP BY item_id) si ON si.item_id=i.id GROUP BY i.id,i.minimum_stock,si.lead_time_days,i.lead_time_days");$balances=[];foreach($inventory as $row)$balances[(int)$row['id']]=['onHand'=>(float)$row['on_hand'],'reserved'=>(float)$row['reserved'],'safety'=>(float)$row['minimum_stock'],'lead'=>(int)$row['lead_days'],'projected'=>max(0,(float)$row['on_hand']-(float)$row['reserved'])];
    $insert=$pdo->prepare("INSERT INTO mrp_requirements (mrp_run_id,item_id,requirement_date,gross_requirement,on_hand_qty,reserved_qty,scheduled_receipts,safety_stock_qty,net_requirement,suggested_order_qty,suggested_order_date,status) VALUES (:run,:item,:date,:gross,:on_hand,:reserved,0,:safety,:net,:suggested,:order_date,:status)");
    foreach($grossRows as $row){$itemId=(int)$row['item_id'];$balance=$balances[$itemId]??['onHand'=>0.0,'reserved'=>0.0,'safety'=>0.0,'lead'=>0,'projected'=>0.0];$gross=(float)$row['gross_requirement'];$net=max(0,$gross+$balance['safety']-$balance['projected']);$orderDate=(new DateTimeImmutable((string)$row['period_start']))->modify('-'.$balance['lead'].' days')->format('Y-m-d');$status=$net>0.000001?'SHORTAGE':'COVERED';$insert->execute(['run'=>$runId,'item'=>$itemId,'date'=>$row['period_start'],'gross'=>$gross,'on_hand'=>max(0,$balance['onHand']),'reserved'=>max(0,$balance['reserved']),'safety'=>max(0,$balance['safety']),'net'=>$net,'suggested'=>$net,'order_date'=>$orderDate,'status'=>$status]);$balance['projected']=max(0,$balance['projected']+$net-$gross);$balances[$itemId]=$balance;}
    $pdo->prepare("UPDATE mrp_runs SET status='COMPLETED',completed_at=UTC_TIMESTAMP(6) WHERE id=:id")->execute(['id'=>$runId]);
    $pdo->prepare("UPDATE alerts SET status='RESOLVED',resolved_at=UTC_TIMESTAMP(6) WHERE alert_type='MRP_SHORTAGE' AND status IN ('OPEN','ACKNOWLEDGED') AND entity_type='mrp_run' AND entity_id IN (SELECT CAST(id AS CHAR) FROM mrp_runs WHERE forecast_version_id=:version AND id<>:run)")->execute(['version'=>$forecastVersionId,'run'=>$runId]);
    $pdo->prepare("INSERT IGNORE INTO alerts (alert_type,severity,title,message,entity_type,entity_id,area_id,status,deduplication_key) SELECT 'MRP_SHORTAGE','WARNING',CONCAT('Faltante: ',i.name),CONCAT('Se necesitan ',ROUND(r.net_requirement,3),' ',u.name,' para ',DATE_FORMAT(r.requirement_date,'%d/%m/%Y'),'. Código: ',i.sku),'mrp_run',CAST(r.mrp_run_id AS CHAR),a.id,'OPEN',CONCAT('MRP_',r.mrp_run_id,'_',r.item_id,'_',r.requirement_date,'_',a.code) FROM mrp_requirements r INNER JOIN items i ON i.id=r.item_id INNER JOIN units_of_measure u ON u.id=i.base_uom_id INNER JOIN areas a ON a.code IN ('COMPRAS','ALMACEN') WHERE r.mrp_run_id=:run AND r.status='SHORTAGE'")->execute(['run'=>$runId]);
    return ['runId'=>$runId,'runNumber'=>$runNumber,'requirements'=>count($grossRows),'missingBillsOfMaterial'=>$missing];
}

function createMaintenanceWorkRequest(PDO $pdo, array $user, array $payload, array $config): array
{
    requirePermission($pdo,(int)$user['id'],'MAINTENANCE','CREATE');$areaId=isSuperAdmin($pdo,(int)$user['id'])?(int)($payload['area_id']??$user['primary_area_id']):(int)$user['primary_area_id'];$area=findOne($pdo,"SELECT id,name FROM areas WHERE id=:id AND is_active=1",['id'=>$areaId],'El área solicitante no es válida.');$assetId=null;if((int)($payload['asset_id']??0)>0){$asset=findOne($pdo,"SELECT id FROM maintenance_assets WHERE id=:id AND is_active=1",['id'=>(int)$payload['asset_id']],'El equipo no existe.');$assetId=$asset['id'];}$priority=strtoupper((string)($payload['priority_code']??'NORMAL'));if(!in_array($priority,['LOW','NORMAL','HIGH','CRITICAL'],true))failRequest('La prioridad no es válida.',422);$needed=new DateTimeImmutable(requiredString($payload,'needed_at','la fecha requerida'),new DateTimeZone('America/Mexico_City'));
    $pdo->beginTransaction();$pdo->prepare("INSERT INTO maintenance_work_requests (request_number,title,description,asset_id,requesting_area_id,location_description,requested_materials,priority_code,needed_at,status,requested_by) VALUES (:number,:title,:description,:asset,:area,:location,:materials,:priority,:needed,'REQUESTED',:user)")->execute(['number'=>provisionalNumber('SOL'),'title'=>requiredString($payload,'title','el título',190),'description'=>requiredString($payload,'description','la descripción',3000),'asset'=>$assetId,'area'=>$area['id'],'location'=>optionalString($payload,'location_description',255),'materials'=>optionalString($payload,'requested_materials',2000),'priority'=>$priority,'needed'=>$needed->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s'),'user'=>$user['id']]);$id=(int)$pdo->lastInsertId();$number=finalNumber('SOL',$id);$pdo->prepare("UPDATE maintenance_work_requests SET request_number=:number WHERE id=:id")->execute(['number'=>$number,'id'=>$id]);writeAudit($pdo,(int)$user['id'],'CREATE','maintenance_work_request',$id,['request_number'=>$number,'area'=>$area['name'],'priority'=>$priority]);$pdo->commit();$recipients=notificationRecipients($pdo,['ALMACEN','MANTENIMIENTO']);queueNotifications($pdo,$config,'MAINTENANCE_REQUEST','maintenance_work_request',$id,$recipients,"Nueva solicitud de Mantenimiento {$number}","Se registró {$number}: ".trim((string)$payload['title']).". Área solicitante: {$area['name']}. Prioridad: {$priority}. Fecha requerida: ".$needed->format('d/m/Y H:i').'.');return ['id'=>$id,'number'=>$number,'notifications'=>count($recipients)];
}

function assignMaintenanceTechnicians(PDO $pdo, array $user, array $payload, array $config): array
{
    $request=findOne($pdo,"SELECT id,request_number,title FROM maintenance_work_requests WHERE id=:id",['id'=>(int)($payload['request_id']??0)],'La solicitud no existe.');if(!isMaintenanceLeader($pdo,$user))failRequest('Solo el administrador o jefe de Mantenimiento puede asignar técnicos.',403);$assignments=$payload['assignments']??[];if(!is_array($assignments)||!$assignments)failRequest('Selecciona al menos un técnico.',422);$pdo->beginTransaction();$assigned=[];foreach($assignments as $entry){$technician=findOne($pdo,"SELECT u.id,u.display_name,u.email FROM maintenance_technicians t INNER JOIN app_users u ON u.id=t.user_id WHERE u.id=:id AND t.is_active=1 AND u.status='ACTIVE'",['id'=>(int)($entry['technician_user_id']??0)],'Uno de los técnicos no está disponible.');$hours=filter_var($entry['estimated_hours']??null,FILTER_VALIDATE_FLOAT);if($hours===false||$hours<=0||$hours>999)failRequest('Las horas estimadas deben ser mayores que cero.',422);$pdo->prepare("INSERT INTO maintenance_work_assignments (work_request_id,technician_user_id,assigned_by,estimated_hours,assignment_status) VALUES (:request,:technician,:user,:hours,'ASSIGNED') ON DUPLICATE KEY UPDATE estimated_hours=VALUES(estimated_hours),assignment_status='ASSIGNED',assigned_by=VALUES(assigned_by),assigned_at=UTC_TIMESTAMP(6)")->execute(['request'=>$request['id'],'technician'=>$technician['id'],'user'=>$user['id'],'hours'=>$hours]);$assigned[]=['name'=>$technician['display_name'],'email'=>$technician['email'],'hours'=>$hours];}$pdo->prepare("UPDATE maintenance_work_requests SET status='ASSIGNED' WHERE id=:id AND status='REQUESTED'")->execute(['id'=>$request['id']]);writeAudit($pdo,(int)$user['id'],'UPDATE','maintenance_work_request',$request['id'],['assigned_technicians'=>array_column($assigned,'name')]);$pdo->commit();foreach($assigned as $technician)queueNotifications($pdo,$config,'MAINTENANCE_ASSIGNED','maintenance_work_request',$request['id'],[['email'=>$technician['email'],'name'=>$technician['name']]],"Tarea de Mantenimiento asignada {$request['request_number']}","Se te asignó la tarea {$request['request_number']}: {$request['title']}. Tiempo estimado: {$technician['hours']} horas. Consulta la aplicación para ver todos los datos y registrar tu intervención.");return ['id'=>(int)$request['id'],'assigned'=>count($assigned)];
}

function updateMaintenanceWork(PDO $pdo, array $user, array $payload, array $config): array
{
    $request=findOne($pdo,"SELECT id,request_number,title FROM maintenance_work_requests WHERE id=:id",['id'=>(int)($payload['request_id']??0)],'La solicitud no existe.');$leader=isMaintenanceLeader($pdo,$user);$assignmentRows=safeRows($pdo,"SELECT id FROM maintenance_work_assignments WHERE work_request_id=:request AND technician_user_id=:user AND assignment_status<>'CANCELLED' LIMIT 1",['request'=>$request['id'],'user'=>$user['id']]);if(!$leader&&!$assignmentRows)failRequest('Esta tarea no está asignada a tu usuario.',403);$assignmentId=$assignmentRows[0]['id']??null;$status=strtoupper((string)($payload['work_status']??''));if(!in_array($status,['IN_PROGRESS','WAITING_PARTS','COMPLETED','VERIFIED'],true))failRequest('El estado de la intervención no es válido.',422);if($status==='VERIFIED'&&!$leader)failRequest('Solo el jefe de Mantenimiento puede verificar el cierre.',403);$hours=filter_var($payload['hours_reported']??0,FILTER_VALIDATE_FLOAT);if($hours===false||$hours<0||$hours>999)failRequest('Las horas reportadas no son válidas.',422);$observations=requiredString($payload,'observations','las observaciones',3000);
    $pdo->beginTransaction();$pdo->prepare("INSERT INTO maintenance_work_updates (work_request_id,assignment_id,status,hours_reported,observations,updated_by) VALUES (:request,:assignment,:status,:hours,:observations,:user)")->execute(['request'=>$request['id'],'assignment'=>$assignmentId,'status'=>$status,'hours'=>$hours,'observations'=>$observations,'user'=>$user['id']]);if($assignmentId!==null){$assignmentStatus=$status==='WAITING_PARTS'?'IN_PROGRESS':$status;$pdo->prepare("UPDATE maintenance_work_assignments SET assignment_status=:status,actual_hours=actual_hours+:hours,work_notes=:notes,started_at=CASE WHEN :status2='IN_PROGRESS' THEN COALESCE(started_at,UTC_TIMESTAMP(6)) ELSE started_at END,completed_at=CASE WHEN :status3='COMPLETED' THEN UTC_TIMESTAMP(6) ELSE completed_at END WHERE id=:id")->execute(['status'=>$assignmentStatus,'hours'=>$hours,'notes'=>$observations,'status2'=>$assignmentStatus,'status3'=>$assignmentStatus,'id'=>$assignmentId]);}$requestStatus=$status;if($status==='COMPLETED'){$remaining=safeScalar($pdo,"SELECT COUNT(*) FROM maintenance_work_assignments WHERE work_request_id=:request AND assignment_status NOT IN ('COMPLETED','CANCELLED')",['request'=>$request['id']]);if($remaining>0)$requestStatus='IN_PROGRESS';}$pdo->prepare("UPDATE maintenance_work_requests SET status=:status,verified_by=CASE WHEN :verify='VERIFIED' THEN :user ELSE verified_by END,verified_at=CASE WHEN :verify2='VERIFIED' THEN UTC_TIMESTAMP(6) ELSE verified_at END WHERE id=:id")->execute(['status'=>$requestStatus,'verify'=>$status,'user'=>$user['id'],'verify2'=>$status,'id'=>$request['id']]);writeAudit($pdo,(int)$user['id'],'UPDATE','maintenance_work_request',$request['id'],['status'=>$requestStatus,'hours'=>$hours],$observations);$pdo->commit();$recipients=notificationRecipients($pdo,['MANTENIMIENTO','ALMACEN']);queueNotifications($pdo,$config,'MAINTENANCE_UPDATED','maintenance_work_request',$request['id'],$recipients,"Actualización de Mantenimiento {$request['request_number']}","La tarea {$request['request_number']} cambió a {$requestStatus}. Horas registradas: {$hours}. Observaciones: {$observations}");return ['id'=>(int)$request['id'],'status'=>$requestStatus];
}

function isMaintenanceLeader(PDO $pdo, array $user): bool
{
    if(isSuperAdmin($pdo,(int)$user['id']))return true;$statement=$pdo->prepare("SELECT 1 FROM areas a WHERE a.id=:area AND a.code='MANTENIMIENTO'");$statement->execute(['area'=>$user['primary_area_id']]);return (bool)$statement->fetchColumn()&&isAreaLeader($pdo,(int)$user['id']);
}

function notificationRecipients(PDO $pdo, array $areaCodes): array
{
    $marks=implode(',',array_fill(0,count($areaCodes),'?'));$statement=$pdo->prepare("SELECT DISTINCT u.email,u.display_name AS name FROM app_users u INNER JOIN areas a ON a.id=u.primary_area_id INNER JOIN user_roles ur ON ur.user_id=u.id AND ur.is_active=1 INNER JOIN roles r ON r.id=ur.role_id WHERE u.status='ACTIVE' AND a.code IN ({$marks}) AND r.code IN ('AREA_ADMIN','AREA_MANAGER','SUPER_ADMIN')");$statement->execute($areaCodes);$rows=$statement->fetchAll()?:[];if(!$rows)$rows=safeRows($pdo,"SELECT u.email,u.display_name AS name FROM app_users u INNER JOIN user_roles ur ON ur.user_id=u.id AND ur.is_active=1 INNER JOIN roles r ON r.id=ur.role_id WHERE r.code='SUPER_ADMIN' AND u.status='ACTIVE' LIMIT 1");return $rows;
}

function queueNotifications(PDO $pdo, array $config, string $event, string $entity, int $entityId, array $recipients, string $subject, string $body): void
{
    $enabled=(bool)($config['notifications']['enabled']??true);$from=(string)($config['notifications']['from_email']??'notificaciones@ci4kash.com');$fromName=(string)($config['notifications']['from_name']??'Oleolab');foreach($recipients as $recipient){$email=trim((string)($recipient['email']??''));if(!filter_var($email,FILTER_VALIDATE_EMAIL))continue;$pdo->prepare("INSERT INTO email_notifications (event_type,entity_type,entity_id,recipient_email,recipient_name,subject_line,delivery_status) VALUES (:event,:entity,:entity_id,:email,:name,:subject,'QUEUED')")->execute(['event'=>$event,'entity'=>$entity,'entity_id'=>(string)$entityId,'email'=>$email,'name'=>$recipient['name']??null,'subject'=>mb_substr($subject,0,255)]);$id=(int)$pdo->lastInsertId();if(!$enabled){$pdo->prepare("UPDATE email_notifications SET delivery_status='SKIPPED',error_message='Notificaciones desactivadas en la configuración' WHERE id=:id")->execute(['id'=>$id]);continue;}$headers=['MIME-Version: 1.0','Content-Type: text/plain; charset=UTF-8','From: '.$fromName.' <'.$from.'>','X-Mailer: Oleolab Almacenes'];$sent=@mail($email,$subject,$body,implode("\r\n",$headers));$pdo->prepare("UPDATE email_notifications SET delivery_status=:status,sent_at=CASE WHEN :sent=1 THEN UTC_TIMESTAMP(6) ELSE NULL END,error_message=:error WHERE id=:id")->execute(['status'=>$sent?'SENT':'FAILED','sent'=>$sent?1:0,'error'=>$sent?null:'El servidor no confirmó la entrega mediante mail()','id'=>$id]);}
}

function uploadMaintenanceEvidence(PDO $pdo, array $user): never
{
    requirePermission($pdo,(int)$user['id'],'MAINTENANCE','UPDATE');$requestId=(int)($_POST['request_id']??0);$request=findOne($pdo,"SELECT id,requested_by FROM maintenance_work_requests WHERE id=:id",['id'=>$requestId],'La solicitud no existe.');$isRequester=(int)$request['requested_by']===(int)$user['id'];if(!isMaintenanceLeader($pdo,$user)&&!$isRequester&&safeScalar($pdo,"SELECT COUNT(*) FROM maintenance_work_assignments WHERE work_request_id=:request AND technician_user_id=:user AND assignment_status<>'CANCELLED'",['request'=>$requestId,'user'=>$user['id']])<1)failRequest('No puedes agregar evidencia a esta tarea.',403);if(!isset($_FILES['evidence'])||!is_uploaded_file($_FILES['evidence']['tmp_name']))failRequest('Selecciona una fotografía.',422);$file=$_FILES['evidence'];if((int)$file['size']<=0||(int)$file['size']>5*1024*1024)failRequest('Cada fotografía debe pesar menos de 5 MB.',413);$finfo=new finfo(FILEINFO_MIME_TYPE);$mime=$finfo->file($file['tmp_name']);$extensions=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($extensions[$mime]))failRequest('Solo se permiten fotografías JPG, PNG o WebP.',422);$directory=dirname(__DIR__).'/storage/private/maintenance';if(!is_dir($directory)&&!mkdir($directory,0750,true)&&!is_dir($directory))failRequest('No fue posible preparar el almacenamiento de evidencias.',500);$storageName=bin2hex(random_bytes(24)).'.'.$extensions[$mime];$destination=$directory.'/'.$storageName;if(!move_uploaded_file($file['tmp_name'],$destination))failRequest('No fue posible guardar la fotografía.',500);$hash=hash_file('sha256',$destination);$original=mb_substr((string)$file['name'],0,255);$pdo->prepare("INSERT INTO file_attachments (entity_type,entity_id,file_name,storage_key,mime_type,file_size_bytes,sha256_hash,uploaded_by) VALUES ('maintenance_work_request',:entity,:name,:key,:mime,:size,:hash,:user)")->execute(['entity'=>(string)$request['id'],'name'=>$original,'key'=>'storage/private/maintenance/'.$storageName,'mime'=>$mime,'size'=>$file['size'],'hash'=>$hash,'user'=>$user['id']]);$id=(int)$pdo->lastInsertId();writeAudit($pdo,(int)$user['id'],'CREATE','maintenance_evidence',$id,['work_request_id'=>$request['id'],'file_name'=>$original]);sendData(['id'=>$id,'fileName'=>$original],201);
}

function streamMaintenanceEvidence(PDO $pdo, array $user, int $evidenceId): never
{
    requirePermission($pdo,(int)$user['id'],'MAINTENANCE','VIEW');$evidence=findOne($pdo,"SELECT f.id,f.entity_id,f.file_name,f.storage_key,f.mime_type,f.file_size_bytes FROM file_attachments f WHERE f.id=:id AND f.entity_type='maintenance_work_request'",['id'=>$evidenceId],'La evidencia no existe.');$requestId=(int)$evidence['entity_id'];$canSee=isSuperAdmin($pdo,(int)$user['id'])||isMaintenanceLeader($pdo,$user)||(isAreaLeader($pdo,(int)$user['id'])&&safeScalar($pdo,"SELECT COUNT(*) FROM maintenance_work_requests WHERE id=:request AND requesting_area_id=:area",['request'=>$requestId,'area'=>$user['primary_area_id']])>0)||safeScalar($pdo,"SELECT COUNT(*) FROM maintenance_work_requests r WHERE r.id=:request AND (r.requested_by=:user OR EXISTS(SELECT 1 FROM maintenance_work_assignments a WHERE a.work_request_id=r.id AND a.technician_user_id=:technician AND a.assignment_status<>'CANCELLED'))",['request'=>$requestId,'user'=>$user['id'],'technician'=>$user['id']])>0;if(!$canSee)failRequest('No puedes consultar esta evidencia.',403);$path=dirname(__DIR__).'/'.ltrim((string)$evidence['storage_key'],'/');if(!is_file($path)){http_response_code(404);exit;}header('Content-Type: '.($evidence['mime_type']?:'application/octet-stream'));header('Content-Length: '.filesize($path));header('Content-Disposition: inline; filename="'.str_replace(['"',"\r","\n"],'',(string)$evidence['file_name']).'"');readfile($path);exit;
}
